<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/config.php';checkSession();if(!checkPermission('compras')){header('Location: '.BASE_URL.'/index.php');exit();}if(empty($_SESSION['csrf_compras']))$_SESSION['csrf_compras']=bin2hex(random_bytes(32));$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['csrf_compras'],$_POST['csrf']??''))$err='La solicitud expiró.';else try{$id=(int)$_POST['id_inventario'];$qty=(int)$_POST['cantidad'];$cost=(float)$_POST['precio_unitario'];if(!$id||$qty<1||$cost<=0)throw new Exception();$total=$qty*$cost;executeQuery("INSERT INTO compras_inventario(id_inventario,cantidad,precio_unitario,total,fecha_compra,proveedor,numero_comprobante,id_usuario_registra,notas) VALUES(?,?,?,?,CURDATE(),?,?,?,?)",[$id,$qty,$cost,$total,trim($_POST['proveedor']),trim($_POST['comprobante']),(int)$_SESSION['user_id'],trim($_POST['notas'])]);$purchaseId=$GLOBALS['db_connection']->insert_id;executeQuery('UPDATE inventario SET cantidad=cantidad+?,precio_unitario=? WHERE id_inventario=?',[$qty,$cost,$id]);executeQuery("INSERT INTO movimientos_inventario(id_inventario,id_usuario,tipo_movimiento,cantidad,motivo) VALUES(?,?,'entrada',?,?)",[$id,(int)$_SESSION['user_id'],$qty,'Compra #'.$purchaseId]);$msg='Compra registrada y existencias actualizadas.';}catch(Throwable $e){$err='Revise el producto, cantidad y costo.';}}$items=getRecords("SELECT id_inventario,nombre_producto,cantidad,precio_unitario,proveedor FROM inventario WHERE estado='activo' ORDER BY nombre_producto");$purchases=getRecords("SELECT c.*,i.nombre_producto FROM compras_inventario c JOIN inventario i ON i.id_inventario=c.id_inventario ORDER BY c.id_compra DESC LIMIT 30");include __DIR__.'/../includes/header.php';?><div class="page-header"><h1>Compras de equipos e inventario</h1><p>Registra adquisiciones y actualiza existencias automáticamente.</p></div><?php if($msg):?><div class="alert alert-success"><?=displayText($msg)?></div><?php endif;?><?php if($err):?><div class="alert alert-danger"><?=displayText($err)?></div><?php endif;?><section class="content-section"><h2>Nueva compra</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['csrf_compras'])?>"><div class="form-group"><label>Equipo o producto *</label><select class="form-control" name="id_inventario" required><option value="">Seleccione</option><?php foreach($items as $i):?><option value="<?=$i['id_inventario']?>"><?=displayText($i['nombre_producto'])?> (existencia: <?=$i['cantidad']?>)</option><?php endforeach;?></select></div><div class="form-group"><label>Cantidad *</label><input class="form-control" type="number" min="1" name="cantidad" required></div><div class="form-group"><label>Costo unitario ($) *</label><input class="form-control" type="number" min="0.01" step="0.01" name="precio_unitario" required></div><div class="form-group"><label>Proveedor</label><input class="form-control" name="proveedor"></div><div class="form-group"><label>Comprobante / referencia</label><input class="form-control" name="comprobante"></div><div class="form-group"><label>Notas</label><input class="form-control" name="notas"></div><button class="btn btn-primary">Registrar compra</button></form></section><section class="content-section mt-20"><h2>Compras recientes</h2><div class="table-responsive"><table class="table"><thead><tr><th>Fecha</th><th>Producto</th><th>Cantidad</th><th>Total</th><th>Proveedor</th><th>Comprobante</th></tr></thead><tbody><?php foreach($purchases as $p):?><tr><td><?=$p['fecha_compra']?></td><td><?=displayText($p['nombre_producto'])?></td><td><?=$p['cantidad']?></td><td>$<?=number_format($p['total'],2)?></td><td><?=displayText($p['proveedor'])?></td><td><?=displayText($p['numero_comprobante'])?></td></tr><?php endforeach;?></tbody></table></div></section><style>.content-section{background:#fff;padding:20px;border-radius:8px;box-shadow:var(--box-shadow)}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 20px}@media(max-width:600px){.form-grid{grid-template-columns:1fr}}</style><?php include __DIR__.'/../includes/footer.php';?>
